namespace QualityReporter.CSharp.Analysis;
public static class ActivityCalculator { public static void Calculate(List<FileResult> files,ActivityWeights w,FileMaturityConfig maturity,DateTimeOffset? now=null){Percentiles.Set(files,x=>x.History.CommitCount,(f,p)=>f.Activity.ChangePercentile=p);Percentiles.Set(files,x=>x.History.Churn,(f,p)=>f.Activity.ChurnPercentile=p);Percentiles.Set(files,x=>x.History.AuthorCount,(f,p)=>f.Activity.AuthorPercentile=p);Percentiles.Set(files,x=>x.History.LastChangedAt?.UtcTicks??0,(f,p)=>f.Activity.RecencyPercentile=p);foreach(var f in files){f.Activity.Score=Percentiles.Weighted((f.Activity.ChangePercentile,w.Change),(f.Activity.ChurnPercentile,w.Churn),(f.Activity.AuthorPercentile,w.Authors),(f.Activity.RecencyPercentile,w.Recency));var age=f.History.FileAgeDays;f.Activity.MaturityFactor=!maturity.Enabled||!age.HasValue?1:age<=7?maturity.FirstWeekFactor:age<=30?maturity.FirstMonthFactor:1;f.Activity.EffectiveScore=Math.Round(f.Activity.Score*f.Activity.MaturityFactor,1);}}}
